  `season` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '季节',
  `rating` int DEFAULT '0' COMMENT '评分',
  `like_count` int DEFAULT '0' COMMENT '点赞数',
