INSERT INTO `community_post` (`id`, `user_id`, `title`, `content`, `images`, `videos`, `like_count`, `comment_count`, `collect_count`, `status`, `create_time`, `update_time`) VALUES (1,1,'北京之行归来，分享一些照片','五一假期去了北京，游览了故宫、长城等景点，人真的很多，但是景色很美。分享一些照片给大家。','[\"https://example.com/post1_1.jpg\", \"https://example.com/post1_2.jpg\"]',NULL,250,80,120,1,'2026-02-14 17:21:56','2026-02-14 17:21:56'),(2,2,'上海美食推荐','作为一个上海本地人，给大家推荐一些地道的上海美食，包括小笼包、生煎包、白斩鸡等。','[\"https://example.com/post2_1.jpg\", \"https://example.com/post2_2.jpg\"]',NULL,180,60,90,1,'2026-02-14 17:21:56','2026-02-14 17:21:56'),(3,3,'杭州西湖一日游攻略','整理了一份西湖一日游的详细攻略，包括最佳游览路线、必看景点、美食推荐等。','[\"https://example.com/post3_1.jpg\", \"https://example.com/post3_2.jpg\"]',NULL,220,70,100,1,'2026-02-14 17:21:56','2026-02-14 17:21:56'),(4,4,'成都大熊猫基地游玩体验','去了成都大熊猫基地，看到了很多可爱的大熊猫，分享一些照片和游玩体验。','[\"https://example.com/post4_1.jpg\", \"https://example.com/post4_2.jpg\"]',NULL,300,90,150,1,'2026-02-14 17:21:56','2026-02-14 17:21:56'),(5,5,'三亚海滩度假心得','在三亚度过了一个愉快的假期，分享一些海滩度假的心得和照片。','[\"https://example.com/post5_1.jpg\", \"https://example.com/post5_2.jpg\"]',NULL,280,85,130,1,'2026-02-14 17:21:56','2026-02-14 17:21:56'),(6,6,'西安兵马俑震撼之旅','参观了秦始皇兵马俑，被其规模和工艺所震撼，分享一些照片和感受。','[\"https://example.com/post6_1.jpg\", \"https://example.com/post6_2.jpg\"]',NULL,200,65,85,1,'2026-02-14 17:21:56','2026-02-14 17:21:56'),(7,7,'厦门鼓浪屿的慢生活','在鼓浪屿度过了两天慢生活，感受了岛上的文艺气息，分享一些照片和体验。','[\"https://example.com/post7_1.jpg\", \"https://example.com/post7_2.jpg\"]',NULL,190,62,88,1,'2026-02-14 17:21:56','2026-02-14 17:21:56'),(8,22,'张家界天门山玻璃栈道体验','挑战了天门山的玻璃栈道，虽然有点害怕，但是风景真的很美，分享一些照片和体验。','http://localhost:8080/upload/fd439b0e-a0d9-4adb-b5db-d237f54656a8.png,http://localhost:8080/upload/146acc31-3846-45f5-b37e-ee2a72d2787d.png,http://localhost:8080/upload/b81c1fae-662b-4fc7-8004-3fe1556a3184.png',NULL,230,75,110,1,'2026-02-14 17:21:56','2026-06-03 23:47:35'),(9,21,'云南大理洱海骑行','在大理洱海骑行，沿途风景如画，分享一些照片和骑行路线推荐。','http://localhost:8080/upload/d1f11e87-b5c5-406f-8053-d2267907a053.png,http://localhost:8080/upload/9ca0dcf4-f204-4865-8b0e-bf87f6e32b99.png,http://localhost:8080/upload/3db42bf1-c68f-4f8c-9e21-61e82007904a.png','',210,68,95,1,'2026-02-14 17:21:56','2026-06-03 23:46:10'),(10,19,'黄山云海日出绝美景色','在黄山山顶等待日出，看到了壮观的云海日出，分享一些照片和拍摄技巧。','http://localhost:8080/upload/981ae605-a712-4166-aaa3-9cc2a48a7aa2.png,http://localhost:8080/upload/b56ff90f-5927-4f16-a061-24988970d2b9.png,http://localhost:8080/upload/d66696da-3e22-49f4-955e-f810383da028.png,http://localhost:8080/upload/dc61e8f2-2839-4582-8a65-9104ddc2eb05.png','',320,95,160,1,'2026-02-14 17:21:56','2026-06-03 23:45:30'),(11,15,'西双版纳一日游','大皖新闻讯“丫头，明年房租再降2万，你放手干！”9月22日晚，合肥潜水街一家小餐馆里，75岁的房东董先生轻描淡写的一句话，让店主杨女士瞬间泪崩。而这已不是他第一次降租——六年来，因目睹杨女士小店经营遭遇困难、女儿患病等困境，这位老人已累计为其减免了房租近10万元。','http://localhost:8080/upload/ed5478f0-0e5e-4c65-adeb-9c3c8fea2b80.png,http://localhost:8080/upload/8251961b-314a-4e20-85d5-93d24b0edc7f.png,http://localhost:8080/upload/284195bb-ad55-4083-8ebd-2b482bb31ee9.jpg',NULL,0,0,0,1,'2026-06-03 23:15:10','2026-09-02 23:46:09');
/*!40000 ALTER TABLE `community_post` ENABLE KEYS */;
UNLOCK TABLES;

