  `image` varchar(155) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '城市图片',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_continent_id` (`continent_id`) USING BTREE,
