INSERT INTO `home_recommendations` (`id`, `uuid`, `name`, `english_name`, `alias_name`, `category_id`, `category_name`, `tags`, `country`, `province`, `city`, `district`, `address`, `longitude`, `latitude`, `google_map_url`, `baidu_map_url`, `transportation`, `recommendation_reason`, `highlights`, `best_travel_time`, `visit_duration`, `cover_image_url`, `banner_image_url`, `video_url`, `image_urls`, `ticket_price_description`, `min_price`, `max_price`, `price_currency`, `is_free`, `opening_hours_weekday`, `opening_hours_weekend`, `opening_hours_description`, `contact_phone`, `official_website`, `social_media`, `view_count`, `like_count`, `share_count`, `comment_count`, `average_rating`, `rating_count`, `weight`, `is_hot`, `is_new`, `is_top`, `status`, `season`, `festival`, `tips`, `suitable_crowd`, `facility_info`, `seo_title`, `seo_keywords`, `seo_description`, `content`, `summary`, `source`, `author`, `created_at`, `updated_at`, `published_at`, `expired_at`) VALUES (1,'082d6297-1d5b-11f1-833c-c4c6e607efc7','故宫博物院','The Palace Museum',NULL,2,'历史文化','世界遗产,拍照圣地,亲子游,研学','中国','北京市','北京市','东城区','景山前街4号',NULL,NULL,NULL,NULL,'地铁1号线天安门东站A口出，步行约10分钟','穿越六百年时光，感受明清两代的皇家气派。故宫不仅是中国古代建筑的精髓，更是中华文明的瑰宝。','三大殿太和殿中和殿保和殿;珍宝馆;钟表馆;故宫角楼;景山俯瞰全景','春秋两季（4月-5月，9月-10月）','半天至一天','http://localhost:8080/upload/9c3efbcb-5afe-4b4f-8bdf-46c58d485660.png',NULL,NULL,'[\"https://example.com/images/gugong_1.jpg\", \"https://example.com/images/gugong_2.jpg\"]','旺季60元/人，淡季40元/人，珍宝馆和钟表馆需另购票',40.00,60.00,'CNY',0,'08:30-17:00','08:30-17:00','每周一闭馆（法定节假日除外）','010-85007421','https://www.dpm.org.cn',NULL,5,0,0,0,0.00,0,100,1,0,0,1,'autumn',NULL,'建议提前网上预约购票，携带身份证入场。避开节假日高峰期，可租讲解器或请导游。','历史文化爱好者,亲子家庭,摄影爱好者',NULL,NULL,NULL,NULL,'故宫博物院建立于1925年，是在明朝、清朝两代皇宫及其收藏的基础上建立起来的中国综合性博物馆。','穿越六百年时光，探寻紫禁城的秘密',NULL,NULL,'2026-03-11 15:00:24','2026-03-11 15:00:24',NULL,NULL),(2,'082daddd-1d5b-11f1-833c-c4c6e607efc7','成都大熊猫繁育研究基地','Chengdu Research Base of Giant Panda Breeding',NULL,1,'自然风光','熊猫,亲子,动物保护,网红','中国','四川省','成都市','成华区','熊猫大道1375号',NULL,NULL,NULL,NULL,'地铁3号线熊猫大道站A口出，转乘景区直通车','近距离观察国宝大熊猫的日常生活，看软萌的熊猫宝宝嬉戏玩耍，是成都必打卡的亲子胜地。','月亮产房看熊猫幼崽;太阳产房;成年熊猫别墅;小熊猫活动区;熊猫博物馆','全年（最佳是春秋季，上午熊猫最活跃）','3-4小时','https://example.com/images/panda_cover.jpg',NULL,NULL,'[\"https://example.com/images/panda_1.jpg\", \"https://example.com/images/panda_2.jpg\"]','成人票55元，学生票27元',27.00,55.00,'CNY',0,'07:30-18:00','07:30-18:00','全年开放','028-83510033','http://www.panda.org.cn',NULL,0,0,0,0,0.00,0,95,1,1,0,1,'spring',NULL,'尽量上午8-10点前往，此时熊猫最活跃，是喂食时间。穿舒适的鞋子，园区较大。','亲子家庭,动物爱好者,自然爱好者',NULL,NULL,NULL,NULL,'成都大熊猫繁育研究基地是一个专门保护和繁育大熊猫、小熊猫等珍稀动物的机构，也是全球最大的大熊猫人工繁育机构。','近距离感受国宝熊猫的萌力暴击',NULL,NULL,'2026-03-11 15:00:24','2026-03-11 15:00:24',NULL,NULL),(3,'4689cc18-1d60-11f1-833c-c4c6e607efc7','上海迪士尼度假区','Shanghai Disney Resort',NULL,3,'主题乐园','亲子,情侣,童话,烟花秀,网红打卡','中国','上海市','上海市','浦东新区','川沙镇黄赵路310号',NULL,NULL,NULL,NULL,'地铁11号线迪士尼站直达','中国大陆首座迪士尼主题乐园，带你进入梦幻童话世界。七大主题园区各具特色，烟花秀震撼人心。','奇幻童话城堡;创极速光轮;加勒比海盗;飞跃地平线;烟花灯光秀;花车巡游','春秋季（避开寒暑假和节假日）','1-2天','http://localhost:8080/upload/d646cecc-0184-47f5-b0e1-b3c9d0c28d91.png',NULL,'https://videos.travel.com/disney_intro.mp4','[\"https://images.travel.com/disney_1.jpg\", \"https://images.travel.com/disney_2.jpg\", \"https://images.travel.com/disney_3.jpg\"]','平日399元，高峰日599元，特别高峰日699元',399.00,699.00,'CNY',0,'09:00-20:30','09:00-21:00','开放时间随季节和活动调整，以官网为准','400-180-0000','https://www.shanghaidisneyresort.com','{\"weibo\": \"上海迪士尼度假区\", \"douyin\": \"shanghaidisney\", \"wechat\": \"ShangHaiDisneyResort\"}',125897,45678,28900,12345,4.80,32000,100,1,0,0,1,'all','圣诞节,春节,万圣节','提前下载官方APP查看排队时间；可购买早享卡提前入园；烟花秀建议提前占位；可带未开封零食和水。','亲子家庭,情侣,年轻人,迪士尼粉丝','有停车场（收费）；有母婴室；提供轮椅和婴儿车租赁；有快速通行证服务','上海迪士尼度假区_门票_攻略_游玩项目','上海迪士尼,迪士尼攻略,主题乐园','上海迪士尼度假区完整攻略：门票价格、开放时间、必玩项目、交通指南、游玩贴士','上海迪士尼度假区是中国内地首座迪士尼主题乐园，于2016年6月正式开园。园区分为米奇大街、奇想花园、探险岛、宝藏湾、明日世界、梦幻世界、玩具总动员七大主题园区。','点亮心中奇梦，重返童年时光','官方合作','迪士尼小编','2026-03-11 15:37:56','2026-03-11 15:37:56','2024-03-01 01:00:00',NULL),(4,'468a1d1e-1d60-11f1-833c-c4c6e607efc7','张家界国家森林公园','Zhangjiajie National Forest Park',NULL,1,'自然风光','自然遗产,登山,摄影,阿凡达,玻璃桥','中国','湖南省','张家界市','武陵源区','金鞭路279号',NULL,NULL,NULL,NULL,'张家界中心汽车站乘景区专线车','电影《阿凡达》取景地，三千奇峰拔地而起，云雾缭绕宛如仙境。是世界自然遗产、世界地质公园。','袁家界哈利路亚山;天子山;金鞭溪;十里画廊;百龙天梯;天门山玻璃栈道','4月-6月，9月-11月（雨后初晴云海最美）','2-3天','https://images.travel.com/zhangjiajie_cover.jpg',NULL,'https://videos.travel.com/zhangjiajie_intro.mp4','[\"https://images.travel.com/zhangjiajie_1.jpg\", \"https://images.travel.com/zhangjiajie_2.jpg\", \"https://images.travel.com/zhangjiajie_3.jpg\"]','森林公园门票228元（4日内有效），天门山门票278元',228.00,278.00,'CNY',0,'07:00-18:00','07:00-18:00','景区旺季延长开放时间','0744-5712333','https://www.zjjpark.com','{\"douyin\": \"zjjtour\", \"wechat\": \"张家界旅游\"}',87652,32100,15400,8760,4.70,18700,98,1,0,0,1,'autumn','国庆节','山路较多，穿舒适运动鞋；景区内环保车免费；建议住一晚武陵源区；注意防猴。','登山爱好者,摄影爱好者,自然探索者','有停车场；山上有简餐售卖点；部分路段有索道和电梯；游客中心可寄存行李','张家界国家森林公园旅游攻略_门票_住宿_交通','张家界,武陵源,阿凡达,玻璃桥','张家界国家森林公园完整攻略：门票价格、开放时间、最佳路线、住宿推荐','张家界国家森林公园位于湖南省张家界市武陵源区，是中国第一个国家森林公园，1992年被列入世界自然遗产名录。公园以独特的石英砂岩峰林地貌著称，有“三千奇峰，八百秀水”之美誉。','探秘阿凡达的悬浮山仙境','小编踩点','张旅行','2026-03-11 15:37:56','2026-03-11 15:37:56','2024-02-15 02:30:00',NULL),(5,'468a2045-1d60-11f1-833c-c4c6e607efc7','回民街','Muslim Quarter',NULL,4,'美食探店','美食,小吃,夜市,历史文化,清真','中国','陕西省','西安市','莲湖区','北院门街道',NULL,NULL,NULL,NULL,'地铁2号线钟楼站下车步行5分钟','西安最著名的小吃街，三百多种美食让你从街头吃到巷尾。青石板路两旁是明清风格建筑，烟火气十足。','牛羊肉泡馍;肉夹馍;凉皮;甑糕;烤肉串;柿子饼;酸梅汤','全年（晚上最热闹）','2-3小时','https://images.travel.com/huiminjie_cover.jpg',NULL,NULL,'[\"https://images.travel.com/huiminjie_1.jpg\", \"https://images.travel.com/huiminjie_2.jpg\"]','丰俭由人，人均消费约50-100元',0.00,0.00,'CNY',0,'全天开放','全天开放','商户一般10:00-23:00营业',NULL,NULL,'{\"douyin\": \"xianfood\"}',45670,18760,8900,5430,4.50,8900,85,1,1,0,1,'all',NULL,'选择人多的店一般不会踩雷；可以每家少吃一点多尝几种；注意清真饮食禁忌。','美食爱好者,吃货,夜猫子','公共厕所在街区两端；部分老店只收现金；有座位的小吃店较少','西安回民街美食攻略_必吃小吃_夜市推荐','回民街,西安美食,小吃街','西安回民街必吃美食清单+避坑指南+营业时间','回民街是西安最具代表性的美食文化街区，距今已有上千年历史。这里聚集了300多种西北特色小吃，是了解西安饮食文化的绝佳去处。','从街头吃到巷尾的西安美食天堂','用户投稿','吃货小马','2026-03-11 15:37:56','2026-03-11 15:37:56','2024-01-20 10:00:00',NULL),(6,'468a242c-1d60-11f1-833c-c4c6e607efc7','洱海','Erhai Lake',NULL,1,'自然风光','洱海,骑行,拍照,民宿,发呆,治愈系','中国','云南省','大理白族自治州','大理市','洱海周边',NULL,NULL,NULL,NULL,'大理古城租电动车或包车环湖','苍山洱海，风花雪月。环湖120公里，每一处都是风景。在双廊看日落，在喜洲吃粑粑，在才村等日出。','环海东路;双廊古镇;喜洲古镇;海舌公园;小普陀;理想邦圣托里尼','3月-5月（樱花季），10月-12月（海鸥季）','2-3天','https://images.travel.com/erhai_cover.jpg',NULL,'https://videos.travel.com/erhai_intro.mp4','[\"https://images.travel.com/erhai_1.jpg\", \"https://images.travel.com/erhai_2.jpg\", \"https://images.travel.com/erhai_3.jpg\"]','免费开放（部分景点单独收费）',0.00,0.00,'CNY',1,'全天开放','全天开放','全天开放',NULL,NULL,'{\"wechat\": \"大理旅游\", \"xiaohongshu\": \"dali\"}',67890,28900,12300,7890,4.85,15600,96,1,0,0,1,'spring','春节','注意防晒；租车记得砍价；海东适合看日落，海西适合看日出；保护环境不乱扔垃圾。','情侣,闺蜜,摄影爱好者,文艺青年','环湖有多个停车场；沿途有公共厕所；民宿集中；有自行车租赁点','大理洱海旅游攻略_环湖路线_民宿推荐','洱海,大理旅游,环洱海','洱海环湖攻略：最佳路线+拍照打卡点+住宿推荐','洱海是云南省第二大高原湖泊，因形状像耳朵而得名。环湖一周约120公里，沿途有双廊、喜洲等多个古镇，是感受大理慢生活的理想之地。','苍山洱海，许你一场风花雪月','小编踩点','风花雪月','2026-03-11 15:37:56','2026-03-11 15:37:56','2024-03-10 06:20:00',NULL),(7,'468a2778-1d60-11f1-833c-c4c6e607efc7','哈尔滨冰雪大世界','Harbin Ice and Snow World',NULL,3,'主题乐园','冰雪,冬季,冰雕,灯光秀,亲子','中国','黑龙江省','哈尔滨市','松北区','松北大道与太阳大道交叉口',NULL,NULL,NULL,NULL,'公交29路、42路冰雪大世界站','世界最大的冰雪主题乐园，用冰雪打造出一个梦幻的童话王国。白天晶莹剔透，夜晚流光溢彩。','冰雕建筑群;超级冰滑梯;冰雪城堡;灯光秀;雪圈;冰雪演出','12月下旬-次年2月底（春节前后最热闹）','4-6小时','https://images.travel.com/ice_cover.jpg',NULL,NULL,'[\"https://images.travel.com/ice_1.jpg\", \"https://images.travel.com/ice_2.jpg\", \"https://images.travel.com/ice_3.jpg\"]','标准票330元，优惠票200元',200.00,330.00,'CNY',0,'11:00-22:00','11:00-22:30','视天气情况调整','0451-58561111','http://www.hrbicesnow.com','{\"weibo\": \"哈尔滨冰雪大世界\"}',54320,23450,8900,4560,4.65,7800,92,1,0,0,1,'winter','元旦,春节','做好保暖，贴暖宝宝；手机贴暖宝宝防止冻关机；下午3点后去能看日夜两种景色。','亲子家庭,年轻人,南方游客','有停车场；园区内有餐饮区；有取暖屋；提供热饮售卖','哈尔滨冰雪大世界攻略_门票_开放时间','冰雪大世界,哈尔滨旅游,冰雕','哈尔滨冰雪大世界游玩攻略：门票价格、保暖贴士、必玩项目','哈尔滨冰雪大世界始创于1999年，每年冬季在松花江畔举办，用松花江的天然冰雪打造出规模宏大的冰雪建筑群，是哈尔滨国际冰雪节的重要组成部分。','闯入零下三十度的冰雪童话世界','官方合作','冰城小编','2026-03-11 15:37:56','2026-03-11 15:37:56','2024-01-