--
-- Table structure for table `hotel_booking`
--

DROP TABLE IF EXISTS `hotel_booking`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `hotel_booking` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键',
  `contact_name` varchar(50) NOT NULL COMMENT '联系人姓名',
  `contact_phone` varchar(20) NOT NULL COMMENT '联系电话',
  `contact_email` varchar(100) DEFAULT NULL COMMENT '联系邮箱',
  `special_request` varchar(500) DEFAULT NULL COMMENT '特殊要求',
  `check_in_date` date NOT NULL COMMENT '入住日期',
  `check_out_date` date NOT NULL COMMENT '退房日期',
  `guests` int unsigned NOT NULL DEFAULT '1' COMMENT '入住人数',
  `room_id` bigint unsigned NOT NULL COMMENT '房间ID',
  `room_name` varchar(100) NOT NULL COMMENT '房间名称',
  `room_price` decimal(10,2) NOT NULL COMMENT '房间单价',
  `room_desc` varchar(255) DEFAULT NULL COMMENT '房间描述',
  `room_facilities` json DEFAULT NULL COMMENT '房间设施(JSON数组)',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '状态:0-待支付,1-已完成,2-已取消',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_check_in_date` (`check_in_date`),
  KEY `idx_contact_phone` (`contact_phone`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='酒店预订表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `hotel_booking`
--

LOCK TABLES `hotel_booking` WRITE;
/*!40000 ALTER TABLE `hotel_booking` DISABLE KEYS */;
/*!40000 ALTER TABLE `hotel_booking` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `hotel_booking_item`
--

DROP TABLE IF EXISTS `hotel_booking_item`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `hotel_booking_item` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键',
  `booking_id` bigint unsigned NOT NULL COMMENT '所属酒店预订ID',
  `hotel_id` bigint NOT NULL COMMENT '酒店ID',
  `hotel_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '酒店名称(快照)',
  `province` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '省份(快照)',
  `city` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '城市(快照)',
  `address` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '地址(快照)',
  `cover_image` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '封面图(快照)',
  `hotel_facilities` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '酒店设施(快照)',
  `rating` int DEFAULT NULL COMMENT '评分(快照)',
  `star_level` int DEFAULT NULL COMMENT '星级(快照)',
