DROP TABLE IF EXISTS `intervention_rule`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `intervention_rule` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '规则唯一标识',
  `rule_code` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '规则编码（全局唯一，供程序引用）',
  `rule_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '规则名称',
  `rule_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '规则类型：RANK-排名筛选 TIME-时间范围 SORT-排序 HIDE-隐藏 PIN-置顶 BOOST-加权（可扩展）',
  `description` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '规则描述',
  `scope_category` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ALL' COMMENT '作用范围：attraction/hotel/food/product，ALL=全部分类',
  `condition_json` json NOT NULL COMMENT '干预条件(JSON)',
  `action_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '干预动作：FILTER/SORT/HIDE/PIN/BOOST（可扩展）',
  `action_params` json DEFAULT NULL COMMENT '干预动作参数(JSON)',
  `priority` int NOT NULL DEFAULT '0' COMMENT '执行优先级，数值越小越先执行',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '生效状态：1-启用 0-停用',
  `effective_start` datetime DEFAULT NULL COMMENT '规则生效开始时间（空=立即生效）',
  `effective_end` datetime DEFAULT NULL COMMENT '规则生效结束时间（空=长期有效）',
  `created_by` bigint DEFAULT NULL COMMENT '创建人（管理员用户ID）',
  `remark` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_rule_code` (`rule_code`),
  KEY `idx_type_status` (`rule_type`,`status`),
  KEY `idx_scope_status` (`scope_category`,`status`),
  KEY `idx_priority` (`priority`)
) ENGINE=InnoDB AUTO_INCREMENT=12 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='业务级人工干预规则表';
/*!40101 SET character_set_client = @saved_cs_client */;

