--
-- Table structure for table `monthly_recommendations`
--

DROP TABLE IF EXISTS `monthly_recommendations`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `monthly_recommendations` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '推荐ID，自增',
  `month_id` int NOT NULL COMMENT '关联月份ID',
  `destination_name` varchar(255) COLLATE utf8mb4_bin NOT NULL COMMENT '目的地名称',
  `image_url` text COLLATE utf8mb4_bin COMMENT '图片URL',
  `description` text COLLATE utf8mb4_bin COMMENT '目的地描述',
  `tags` json DEFAULT NULL COMMENT '标签（JSON数组格式，如：["雪山","滑雪","温泉"]）',
  `season_features` varchar(500) COLLATE utf8mb4_bin DEFAULT NULL COMMENT '当季特色',
  `climate_info` varchar(500) COLLATE utf8mb4_bin DEFAULT NULL COMMENT '气候信息',
  `travel_tips` text COLLATE utf8mb4_bin COMMENT '旅行小贴士',
  `recommended_days` tinyint DEFAULT NULL COMMENT '建议游玩天数',
  `sort_order` int DEFAULT '0' COMMENT '排序顺序（数字越小越靠前）',
  `is_recommended` tinyint(1) DEFAULT '1' COMMENT '是否推荐（0：不推荐，1：推荐）',
  `view_count` int DEFAULT '0' COMMENT '浏览次数',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_month_id` (`month_id`) COMMENT '月份ID索引',
  KEY `idx_is_recommended` (`is_recommended`) COMMENT '推荐状态索引',
  KEY `idx_sort_order` (`sort_order`) COMMENT '排序索引',
  CONSTRAINT `monthly_recommendations_ibfk_1` FOREIGN KEY (`month_id`) REFERENCES `months` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=59 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin COMMENT='月份旅行推荐内容表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `monthly_recommendations`
--

LOCK TABLES `monthly_recommendations` WRITE;
/*!40000 ALTER TABLE `monthly_recommendations` DISABLE KEYS */;
INSERT INTO `monthly_recommendations` (`id`, `month_id`, `destination_name`, `image_url`, `description`, `tags`, `season_features`, `climate_info`, `travel_tips`, `recommended_days`, `sort_order`, `is_recommended`, `view_count`, `created_at`, `updated_at`) VALUES (1,1,'哈尔滨','data:image/webp;base64,','冰雪之城，冬季旅游胜地','[\"冰雪\", \"冰雕\", \"滑雪\"]','哈尔滨国际冰雪节，欣赏精美冰雕雪雕','气温约-20℃至-10℃，寒冷干燥','注意保暖，穿羽绒服、雪地靴，携带保温杯',3,1,1,0,'2026-02-22 14:23:06','2026-06-06 15:47:34'),(2,2,'三亚','data:image/jpeg;base64,','避寒胜地，热带海滨风光','[\"海滩\", \"阳光\", \"海鲜\"]','温暖如春，适合避寒度假','气温约20℃-28℃，舒适宜人','防晒必备，可下海游泳',4,2,1,0,'2026-02-22 14:23:06','2026-06-06 15:52:16'),(3,1,'长白山','http://localhost:8080/upload/833a8847-1877-4131-8f7b-86c895f6f458.jpg','冬季滑雪泡温泉的绝佳去处','[\"滑雪\", \"温泉\", \"雪景\"]','林海雪原，雾凇奇观','气温约-25℃至-15℃，山区更冷','滑雪需注意安全，泡温泉要控制时间',3,3,1,0,'2026-02-22 14:23:06','2026-09-02 15:47:55'),(4,1,'昆明','/images/kunming.jpg','春城，四季如春','[\"暖冬\", \"花卉\", \"民族风情\"]','冬季温暖，鲜花盛开','气温约5℃-18℃，早晚温差大','早晚需穿外套，可游览滇池、石林',2,4,1,0,'2026-02-22 14:23:06','2026-02-22 14:23:06'),(5,7,'青岛','/images/qingdao.jpg','海滨城市，避暑胜地','[\"海滩\", \"啤酒\", \"海鲜\"]','青岛国际啤酒节，海滨浴场开放','气温约22℃-28℃，凉爽海风','品尝海鲜啤酒，注意防晒',3,1,1,0,'2026-02-22 14:23:06','2026-02-22 14:23:06'),(6,7,'承德避暑山庄','/images/chengde.jpg','清代皇家避暑胜地','[\"古迹\", \"避暑\", \"园林\"]','山区凉爽，适合避暑','气温约20℃-28℃，山区凉爽','游览皇家园林，了解清代历史',2,2,1,0,'2026-02-22 14:23:06','2026-02-22 14:23:06'),(7,7,'九寨沟','/images/jiuzhaigou.jpg','童话世界，夏季水量充沛','[\"山水\", \"瀑布\", \"原始森林\"]','水量充沛，瀑布壮观','气温约15℃-25℃，昼夜温差大','带雨具，注意高原反应',4,3,1,0,'2026-02-22 14:23:06','2026-02-22 14:23:06'),(8,7,'呼伦贝尔','/images/hulunbeier.jpg','大草原最美的季节','[\"草原\", \"骑马\", \"蒙古包\"]','草原最美季节，那达慕大会','气温约18℃-28℃，昼夜温差大','体验草原文化，骑马需注意安全',4,4,1,0,'2026-02-22 14:23:06','2026-06-06 15:53:15'),(9,1,'哈尔滨','https://picsum.photos/seed/mr1/800/600','冰雪之城，冬季必打卡的北国风光。','[\"冰雪\", \"滑雪\", \"冰雕\", \"温泉\"]','冰雪大世界、太阳岛雪博会、亚布力滑雪','零下15℃至零下30℃，干冷多雪','注意保暖，穿羽绒服、雪地靴，备好暖宝宝。',4,1,1,1200,'2026-10-04 13:32:58','2026-10-04 13:32:58'),(10,1,'三亚','https://picsum.photos/seed/mr2/800/600','避寒胜地，冬日里的热带天堂。','[\"海滨\", \"阳光\", \"沙滩\", \"潜水\"]','温暖如夏，海鲜肥美，游客相对较少','20℃-28℃，温暖湿润','防晒必备，提前预订海景酒店。',5,2,1,1100,'2026-10-04 13:32:58','2026-10-04 13:32:58'),(11,1,'长白山','https://picsum.photos/seed/mr3/800/600','林海雪原，温泉与滑雪的完美结合。','[\"雪山\", \"滑雪\", \"温泉\", \"雾凇\"]','天池冰封，温泉热雾蒸腾，雪期长','零下20℃至零下10℃，寒冷干燥','备好防寒装备，泡温泉注意温差。',3,3,1,900,'2026-10-04 13:32:58','2026-10-04 13:32:58'),(12,1,'西双版纳','https://picsum.photos/seed/mr4/800/600','热带雨林，冬日暖阳下的傣乡风情。','[\"雨林\", \"傣族\", \"暖冬\", \"热带\"]','气候宜人，泼水节预热，热带水果丰富','15℃-25℃，温暖少雨','带好防蚊用品，尊重当地民族习俗。',4,4,1,850,'2026-10-04 13:32:58','2026-10-04 13:32:58'),(13,2,'丽江','https://picsum.photos/seed/mr5/800/600','古城慢生活，雪山与古镇的浪漫邂逅。','[\"古城\", \"雪山\", \"文艺\", \"慢生活\"]','玉龙雪山雪景最佳，古城年味浓','5℃-18℃，昼夜温差大','注意防晒，古城内住宿建议提前预订。',4,1,1,1150,'2026-10-04 13:32:58','2026-10-04 13:32:58'),(14,2,'厦门','https://picsum.photos/seed/mr6/800/600','海上花园，温暖文艺的闽南之城。','[\"海岛\", \"文艺\", \"美食\", \"鼓浪屿\"]','气候温和，游人较少，适合慢游','12℃-20℃，温和湿润','带薄外套，鼓浪屿船票需提前预订。',3,2,1,1000,'2026-10-04 13:32:58','2026-10-04 13:32:58'),(15,2,'桂林','https://picsum.photos/seed/mr7/800/600','山水甲天下，烟雨漓江如诗如画。','[\"山水\", \"漓江\", \"摄影\", \"自然\"]','烟雨漓江，水墨意境，游客不多','8℃-18℃，多雨雾','备雨具，乘竹筏游漓江注意保暖。',3,3,1,880,'2026-10-04 13:32:58','2026-10-04 13:32:58'),(16,2,'昆明','https://picsum.photos/seed/mr8/800/600','春城无处不飞花，四季如春的宜居之城。','[\"春城\", \"花海\", \"红嘴鸥\", \"温泉\"]','红嘴鸥盘旋滇池，郁金香盛开','10℃-22℃，四季如春','早晚温差大，带件外套。',3,4,1,820,'2026-10-04 13:32:58','2026-10-04 13:32:58'),(17,3,'婺源','https://picsum.photos/seed/mr9/800/600','中国最美乡村，油菜花海的金色春天。','[\"油菜花\", \"古村\", \"摄影\", \"春天\"]','油菜花海盛开，徽派古村如画','10℃-20℃，春意盎然','花季人多，建议错峰出行，提前订房。',3,1,1,1300,'2026-10-04 13:32:58','2026-10-04 13:32:58'),(18,3,'武汉','https://picsum.photos/seed/mr10/800/600','樱花之城，春日浪漫的江城风情。','[\"樱花\", \"赏花\", \"美食\", \"江城\"]','武大樱花、东湖樱花盛开','10℃-20℃，温暖湿润','樱花季人多，建议早上去武大赏樱。',3,2,1,1200,'2026-10-04 13:32:58','2026-10-04 13:32:58'),(19,3,'林芝','https://picsum.photos/seed/mr11/800/600','西藏江南，桃花盛开的雪域秘境。','[\"桃花\", \"雪山\", \"高原\", \"摄影\"]','桃花沟桃花盛开，雪山映衬','5℃