LOCK TABLES `news` WRITE;
/*!40000 ALTER TABLE `news` DISABLE KEYS */;
INSERT INTO `news` (`id`, `title`, `content`, `cover_image`, `source`, `view_count`, `like_count`, `collect_count`, `comment_count`, `status`, `create_time`, `update_time`) VALUES (3,'2024年五一假期旅游市场火爆，国内游人次突破2亿','据文化和旅游部数据中心测算，2024年五一假期全国国内旅游出游人次达到2.1亿，同比增长120%，旅游收入达到1200亿元，同比增长150%。','http://localhost:8080/upload/f3235027-bacf-4650-a976-e634e1a3a266.png','人民日报',50014,2000,1500,800,1,'2026-02-14 17:21:56','2026-03-08 14:49:56'),(4,'故宫博物院推出\"清明上河图3.0\"数字艺术展','故宫博物院将于5月1日起推出\"清明上河图3.0\"数字艺术展，通过现代科技手段重现北宋都城汴京的繁华景象。','http://localhost:8080/upload/006a97b8-0305-4916-9a60-a7294505654b.png','新华社',35004,1500,1200,600,1,'2026-02-14 17:21:56','2026-04-05 13:25:31'),(5,'三亚国际旅游岛建设取得新进展，免税购物销售额突破500亿','三亚国际旅游岛建设近年来取得显著成效，2024年第一季度免税购物销售额达到520亿元，同比增长35%。','https://example.com/news3.jpg','海南日报',28001,1200,900,450,1,'2026-02-14 17:21:56','2026-02-14 17:21:56'),(6,'2024年中国国际旅游交易会在上海开幕','为期三天的2024年中国国际旅游交易会在上海新国际博览中心开幕，来自全球50多个国家和地区的旅游机构参展。','https://example.com/news4.jpg','上海日报',25000,1000,800,400,1,'2026-02-14 17:21:56','2026-02-14 17:21:56'),(7,'中国高铁旅游线路成为热门选择，\"高铁游\"成新趋势','随着高铁网络的不断完善，\"高铁游\"成为越来越多游客的选择。2024年第一季度，高铁沿线城市旅游收入同比增长45%。','https://example.com/news5.jpg','经济日报',32000,1300,1000,550,1,'2026-02-14 17:21:56','2026-02-14 17:21:56'),(8,'九寨沟景区将于4月1日起恢复全域开放','经过两年的生态修复，九寨沟景区将于2024年4月1日起恢复全域开放，开放区域包括之前因地震关闭的部分景点。','https://example.com/news6.jpg','四川日报',40001,1800,1300,700,1,'2026-02-14 17:21:56','2026-02-14 17:21:56'),(9,'2024年中国旅游日主题确定为\"美好中国，幸福旅程\"','文化和旅游部宣布，2024年中国旅游日主题为\"美好中国，幸福旅程\"，全国各地将推出多项旅游惠民措施。','https://example.com/news7.jpg','文旅部官网',22000,900,700,350,1,'2026-02-14 17:21:56','2026-02-14 17:21:56'),(10,'北京冬奥会场馆成为热门旅游景点，年接待游客突破1000万','北京冬奥会结束后，冬奥会场馆成为热门旅游景点。2023年，冬奥会场馆群共接待游客1050万人次，旅游收入达到80亿元。','https://example.com/news8.jpg','北京日报',38001,1600,1100,650,1,'2026-02-14 17:21:56','2026-02-14 17:21:56'),(11,'全国首个\"智慧旅游城市\"试点在杭州启动','杭州市成为全国首个\"智慧旅游城市\"试点，通过大数据、人工智能等技术，为游客提供更加便捷、个性化的旅游服务。','https://example.com/news9.jpg','科技日报',26001,1100,850,420,1,'2026-02-14 17:21:56','2026-02-14 17:21:56'),(12,'中国出境游市场逐步恢复，2024年第一季度出境游人次同比增长200%','随着全球疫情防控形势的好转，中国出境游市场逐步恢复。2024年第一季度，中国公民出境游人次达到1200万，同比增长200%。','http://localhost:8080/upload/01a608e4-d51e-424e-b293-05d35bc53816.png','环球时报',45008,1900,1400,750,1,'2026-02-14 17:21:56','2026-04-05 13:30:59');
/*!40000 ALTER TABLE `news` ENABLE KEYS */;
UNLOCK TABLES;

