CREATE TABLE `order_shipping` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '发货单ID',
  `shipping_no` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '发货单号',
  `order_id` bigint NOT NULL COMMENT '订单ID',
  `order_no` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '订单号',
  `user_id` bigint NOT NULL COMMENT '用户ID',
  `item_type` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '商品类型 ticket/product/food...',
  `item_id` bigint DEFAULT NULL COMMENT '商品ID',
  `item_name` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '商品名称',
  `item_image` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '商品图片',
  `quantity` int NOT NULL DEFAULT '1' COMMENT '本包裹数量',
  `carrier_id` bigint DEFAULT NULL COMMENT '承运商ID',
  `carrier_code` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '承运商编码',
  `tracking_no` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '运单号',
  `receiver_name` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '收件人',
  `receiver_phone` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '收件电话',
  `receiver_address` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '收件地址',
  `package_weight` decimal(10,3) DEFAULT NULL COMMENT '包裹重量kg',
  `freight` decimal(10,2) DEFAULT NULL COMMENT '运费',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '0-待发货 1-已发货 2-运输中 3-派送中 4-已签收 5-拒收 6-退回 7-异常',
  `ship_time` datetime DEFAULT NULL COMMENT '发货时间',
  `receive_time` datetime DEFAULT NULL COMMENT '签收时间',
  `expect_time` datetime DEFAULT NULL COMMENT '预计送达',
  `remark` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_shipping_no` (`shipping_no`),
  KEY `idx_order` (`order_id`),
  KEY `idx_user` (`user_id`),
  KEY `idx_tracking` (`tracking_no`),
  KEY `idx_status` (`status`,`create_time`)
) ENGINE=InnoDB AUTO_INCREMENT=13 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='发货单表';
