--
-- Table structure for table `recommendation_config`
--

DROP TABLE IF EXISTS `recommendation_config`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `recommendation_config` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `scope` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'GLOBAL' COMMENT '作用域 GLOBAL-全局 CATEGORY-分类',
  `category` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '分类编码（attraction/hotel/food/product），GLOBAL 时为空串',
  `param_key` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '参数键',
  `param_value` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '参数值（字符串存储，按 value_type 解析）',
  `value_type` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'STRING' COMMENT '值类型 NUMBER/BOOLEAN/STRING',
  `description` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '参数说明',
  `updated_by` bigint DEFAULT NULL COMMENT '最后更新人（管理员用户ID）',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_scope_category_key` (`scope`,`category`,`param_key`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=101 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='推荐算法参数配置表';
/*!40101 SET character_set_client = @saved_cs_client */;

