--
-- Table structure for table `recommendation_exposure_log`
--

DROP TABLE IF EXISTS `recommendation_exposure_log`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `recommendation_exposure_log` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `user_id` bigint DEFAULT NULL COMMENT '用户ID（匿名曝光为空）',
  `category` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '分类编码 attraction/hotel/food/product',
  `item_id` bigint NOT NULL COMMENT '曝光物品ID',
  `score` decimal(10,4) NOT NULL DEFAULT '0.0000' COMMENT '曝光时的推荐分',
  `rank_position` int NOT NULL COMMENT '展示排名（从1开始）',
  `source` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'POPULAR' COMMENT '推荐来源 PERSONALIZED/POPULAR/FEATURED/COLD_START',
  `request_id` varchar(48) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '请求ID（同一次列表请求共享）',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '曝光时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_created_at` (`created_at`) USING BTREE,
  KEY `idx_category_created` (`category`,`created_at`) USING BTREE,
  KEY `idx_user_created` (`user_id`,`created_at`) USING BTREE,
  KEY `idx_category_item_created` (`category`,`item_id`,`created_at`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='推荐曝光日志表';
/*!40101 SET character_set_client = @saved_cs_client */;

