INSERT INTO `safetytips` (`id`, `title`, `description`, `image_url`, `category_id`, `sort_weight`, `status`, `creator_id`, `updater_id`, `create_time`, `update_time`) VALUES (31,'旅游前的准备工作','旅游前要检查身份证、护照等证件，准备好常用药品，了解目的地的天气情况...','https://example.com/safety1.jpg',NULL,1,1,NULL,NULL,'2025-12-21 12:02:13','2025-12-21 12:02:13'),(32,'在景区游玩的安全注意事项','在景区游玩时要遵守景区规定，不要离开指定路线，注意防滑防摔...','https://example.com/safety2.jpg',NULL,2,1,NULL,NULL,'2025-12-21 12:02:13','2025-12-21 12:02:13'),(33,'食品安全注意事项','在旅游过程中要注意饮食卫生，避免食用生冷食物，选择正规餐厅...','https://example.com/safety3.jpg',NULL,3,1,NULL,NULL,'2025-12-21 12:02:13','2025-12-21 12:02:13'),(34,'交通安全注意事项','在旅游过程中要遵守交通规则，选择正规的交通工具，系好安全带...','https://example.com/safety4.jpg',NULL,4,1,NULL,NULL,'2025-12-21 12:02:13','2025-12-21 12:02:13'),(35,'财物安全注意事项','在旅游过程中要保管好个人财物，避免携带大量现金，注意防盗防骗...','https://example.com/safety5.jpg',NULL,5,1,NULL,NULL,'2025-12-21 12:02:13','2025-12-21 12:02:13'),(36,'应急处理方法','在旅游过程中如果遇到紧急情况，要保持冷静，及时拨打当地的紧急救援电话...','https://example.com/safety6.jpg',NULL,6,1,NULL,NULL,'2025-12-21 12:02:13','2025-12-21 12:02:13'),(37,'高原旅游注意事项','在高原地区旅游时要注意预防高原反应，避免剧烈运动，保持充足的睡眠...','http://localhost:8080/upload/3f97a241-32b5-486d-a411-75c9785d7125.png',NULL,7,1,NULL,NULL,'2025-12-21 12:02:13','2026-09-02 23:58:46'),(38,'水上活动安全注意事项','在进行水上活动时要穿戴好救生设备，听从教练的指导，不要独自下水...','http://localhost:8080/upload/bc35257c-6f47-4b18-983f-ce676ee26b22.jpg',NULL,8,1,NULL,NULL,'2025-12-21 12:02:13','2026-09-02 23:58:35'),(39,'登山安全注意事项','在登山时要选择合适的装备，遵循登山路线，注意天气变化...','http://localhost:8080/upload/f43aa3b9-d413-4f8c-ab15-87e51d8ccb03.jpg',NULL,9,1,NULL,NULL,'2025-12-21 12:02:13','2026-09-02 23:58:25'),(40,'夜间出行安全注意事项','在夜间出行时要选择明亮的路线，避免前往偏僻的地方，注意自身安全...','http://localhost:8080/upload/e43d21d9-02d5-453a-82fb-ce9e04389950.png',NULL,10,1,NULL,NULL,'2025-12-21 12:02:13','2025-12-21 12:02:13');
