--
-- Table structure for table `souvenirs_recommendations`
--

DROP TABLE IF EXISTS `souvenirs_recommendations`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `souvenirs_recommendations` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `item_id` bigint NOT NULL COMMENT '商品ID（product.id）',
  `recommendation_score` decimal(10,4) NOT NULL DEFAULT '0.0000' COMMENT '综合推荐分（全局/匿名口径，0-1）',
  `user_preference_matching` decimal(8,4) NOT NULL DEFAULT '0.0000' COMMENT '用户偏好匹配分（内容标签群体亲和度，0-1）',
  `popularity_index` decimal(8,4) NOT NULL DEFAULT '0.0000' COMMENT '热度指数（对数压缩+归一化，0-1）',
  `collaborative_score` decimal(8,4) NOT NULL DEFAULT '0.0000' COMMENT '协同过滤分（物品共现相似度聚合，0-1）',
  `content_score` decimal(8,4) NOT NULL DEFAULT '0.0000' COMMENT '内容质量/标签丰富度分（0-1）',
  `seasonal_score` decimal(8,4) NOT NULL DEFAULT '0.0000' COMMENT '季节趋势分（0-1）',
  `quality_score` decimal(8,4) NOT NULL DEFAULT '0.0000' COMMENT '品质分（评分归一化，0-1）',
  `is_featured` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否人工置顶推荐 0-否 1-是',
  `feature_weight` decimal(8,4) NOT NULL DEFAULT '0.0000' COMMENT '人工加权系数（置顶/boost 强度）',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '状态 0-排除（不参与推荐） 1-正常',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `update_timestamp` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '推荐分更新时间戳',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_item_id` (`item_id`) USING BTREE,
  KEY `idx_status_score` (`status`,`recommendation_score`) USING BTREE,
  KEY `idx_featured` (`is_featured`) USING BTREE,
  CONSTRAINT `fk_souv_rec_item` FOREIGN KEY (`item_id`) REFERENCES `product` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=312 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='纪念品（特产）推荐结果表';
/*!40101 SET character_set_client = @saved_cs_client */;

