--
-- Table structure for table `travel_note`
--

DROP TABLE IF EXISTS `travel_note`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `travel_note` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `user_id` bigint NOT NULL COMMENT '作者ID',
  `title` varchar(120) NOT NULL COMMENT '标题',
  `summary` varchar(300) DEFAULT NULL COMMENT '摘要',
  `cover_url` varchar(500) DEFAULT NULL COMMENT '封面图URL',
  `content` longtext COMMENT '正文(HTML/Markdown)',
  `content_type` tinyint NOT NULL DEFAULT '1' COMMENT '内容类型: 1-HTML 2-Markdown',
  `destination` varchar(100) DEFAULT NULL COMMENT '目的地文本',
  `continent_id` bigint DEFAULT NULL COMMENT '大洲ID(continents.id)',
  `country_id` bigint DEFAULT NULL COMMENT '国家ID(countries.id)',
  `city_id` bigint DEFAULT NULL COMMENT '城市ID(cities.id)',
  `travel_days` int DEFAULT NULL COMMENT '旅行天数',
  `travel_date` date DEFAULT NULL COMMENT '出行日期',
  `cost` decimal(10,2) DEFAULT NULL COMMENT '人均花费',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '状态: 0-草稿 1-待审 2-已发布 3-驳回 4-下架 5-私密',
  `is_top` tinyint NOT NULL DEFAULT '0' COMMENT '是否置顶: 0-否 1-是',
  `is_featured` tinyint NOT NULL DEFAULT '0' COMMENT '是否加精: 0-否 1-是',
  `view_count` int NOT NULL DEFAULT '0' COMMENT '浏览量',
  `like_count` int NOT NULL DEFAULT '0' COMMENT '点赞数',
  `collect_count` int NOT NULL DEFAULT '0' COMMENT '收藏数',
  `comment_count` int NOT NULL DEFAULT '0' COMMENT '评论数',
  `share_count` int NOT NULL DEFAULT '0' COMMENT '分享数',
  `reject_reason` varchar(255) DEFAULT NULL COMMENT '驳回原因',
  `publish_time` datetime DEFAULT NULL COMMENT '发布时间',
  `deleted` tinyint NOT NULL DEFAULT '0' COMMENT '逻辑删除: 0-正常 1-已删除',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_user` (`user_id`,`status`),
  KEY `idx_city_status` (`city_id`,`status`,`publish_time`),
  KEY `idx_publish` (`status`,`publish_time`),
  KEY `idx_featured` (`status`,`is_top`,`is_featured`)
) ENGINE=InnoDB AUTO_INCREMENT=12 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='旅游笔记';
/*!40101 SET character_set_client = @saved_cs_client */;

