LOCK TABLES `travel_note` WRITE;
/*!40000 ALTER TABLE `travel_note` DISABLE KEYS */;
INSERT INTO `travel_note` (`id`, `user_id`, `title`, `summary`, `cover_url`, `content`, `content_type`, `destination`, `continent_id`, `country_id`, `city_id`, `travel_days`, `travel_date`, `cost`, `status`, `is_top`, `is_featured`, `view_count`, `like_count`, `collect_count`, `comment_count`, `share_count`, `reject_reason`, `publish_time`, `deleted`, `create_time`, `update_time`) VALUES (1,1,'云南七日：从昆明到大理的慢旅行','避开人潮，沿着滇西走一圈，把苍山洱海装进相机。','https://oss.minecraft.com/note/cover/yunnan01.jpg','<p>第一天抵达昆明，去了翠湖公园……</p>',1,'云南·大理',1,1,1,7,'2026-03-15',3800.00,2,1,1,12801,860,420,96,58,NULL,'2026-03-25 10:20:00',0,'2026-03-22 09:00:00','2026-10-11 16:40:00'),(2,2,'成都三日吃货地图：从早茶吃到夜宵','一份不踩雷的成都美食清单，含人均与排队攻略。','https://oss.minecraft.com/note/cover/chengdu01.jpg','<p>早上先去人民公园喝盖碗茶……</p>',1,'四川·成都',1,1,2,3,'2026-04-01',1200.00,2,0,1,9600,720,380,74,41,NULL,'2026-04-05 18:30:00',0,'2026-04-03 14:00:00','2026-10-11 16:08:55'),(3,3,'青海湖环湖自驾：3 天 800 公里的自由','含加油点、住宿、拍照机位，适合第一次自驾的人。','https://oss.minecraft.com/note/cover/qinghai01.jpg','<p>西宁出发，第一天到黑马河看日出……</p>',1,'青海·海南州',1,1,3,3,'2026-06-10',2200.00,2,0,0,7300,510,260,52,30,NULL,'2026-06-15 08:00:00',0,'2026-06-12 20:00:00','2026-10-11 16:08:55'),(4,4,'京都赏樱 5 日：避开人潮的 6 个小众机位','樱花季不挤人，含交通与和服租赁建议。','https://oss.minecraft.com/note/cover/kyoto01.jpg','<p>哲学之道清晨 6 点几乎没人……</p>',1,'日本·京都',2,2,4,5,'2026-03-28',8600.00,2,1,1,21500,1680,920,143,102,NULL,'2026-04-02 12:00:00',0,'2026-03-30 10:00:00','2026-10-11 16:08:55'),(5,5,'三亚亲子 5 日：带 3 岁娃也能轻松玩','含婴儿车友好景点、亲子酒店与辅食攻略。','https://oss.minecraft.com/note/cover/sanya01.jpg','<p>选酒店优先看有没有儿童俱乐部……</p>',1,'海南·三亚',1,1,5,5,'2026-02-10',6800.00,2,0,0,5400,430,210,38,22,NULL,'2026-02-18 15:00:00',0,'2026-02-15 11:00:00','2026-10-11 16:08:55'),(6,6,'西安 48 小时：兵马俑 + 城墙 + 回民街','周末短途，含门票预约与避坑指南。','https://oss.minecraft.com/note/cover/xian01.jpg','<p>兵马俑一定要提前 3 天预约……</p>',1,'陕西·西安',1,1,6,2,'2026-05-01',900.00,2,0,0,4100,320,150,27,15,NULL,'2026-05-04 20:00:00',0,'2026-05-02 09:30:00','2026-10-11 16:08:55'),(7,7,'冰岛环岛 10 日：追极光与冰川徒步','含租车、加油、天气预警与拍摄参数。','https://oss.minecraft.com/note/cover/iceland01.jpg','<p>雷克雅未克取车后先买加油卡……</p>',1,'冰岛·雷克雅未克',3,3,7,10,'2026-09-20',26000.00,2,1,1,18200,1420,760,118,86,NULL,'2026-10-05 22:00:00',0,'2026-10-02 16:00:00','2026-10-11 16:08:55'),(8,8,'重庆 3 日：8D 魔幻城市暴走指南','轻轨穿楼、洪崖洞、山城步道，含防迷路贴士。','https://oss.minecraft.com/note/cover/chongqing01.jpg','<p>导航在重庆经常失效，认路标比认地图重要……</p>',1,'重庆·渝中区',1,1,8,3,'2026-07-12',1500.00,2,0,0,6200,480,230,45,28,NULL,'2026-07-18 19:00:00',0,'2026-07-15 13:00:00','2026-10-11 16:08:55'),(9,9,'西藏 8 日：拉萨 + 林芝 + 羊湖','含高反应对、边防证办理与包车建议。','https://oss.minecraft.com/note/cover/tibet01.jpg','<p>进藏前一周开始吃红景天……</p>',1,'西藏·拉萨',1,1,9,8,'2026-08-05',9800.00,2,1,0,15400,1180,640,102,74,NULL,'2026-08-14 11:00:00',0,'2026-08-10 09:00:00','2026-10-11 16:48:39'),(10,10,'厦门 4 日：鼓浪屿 + 环岛路 + 沙坡尾','文艺小城慢游，含轮渡购票与民宿推荐。','https://oss.minecraft.com/note/cover/xiamen01.jpg','<p>鼓浪屿船票要提前 1 天在官方渠道买……</p>',1,'福建·厦门',1,1,10,4,'2026-04-20',2600.00,2,0,0,5900,450,220,41,25,NULL,'2026-04-25 16:00:00',0,'2026-04-22 10:00:00','2026-10-11 16:08:55'),(11,15,'哈哈','哈哈哈','','一天好几个看',1,'昆明',NULL,NULL,NULL,1,'2026-10-11',33.00,2,0,0,0,0,0,0,0,NULL,'2026-10-11 16:41:11',0,'2026-10-11 16:40:51','2026-10-11 16:41:11');
/*!40000 ALTER TABLE `travel_note` ENABLE KEYS */;
UNLOCK TABLES;

