INSERT INTO `worldcharacteristics` (`id`, `name`, `country`, `image`, `description`, `features`, `history`, `culture`, `tags`, `category`, `color`) VALUES (25,'长城','中国','http://localhost:8080/upload/27ddbd99-e568-4f61-aedd-08c4faea7aff.png','中国古代的军事防御工程','世界文化遗产','始建于西周时期','中国古代文化的象征','长城,历史,文化','历史建筑','#FF0000'),(26,'埃菲尔铁塔','法国','https://example.com/world2.jpg','法国巴黎的标志性建筑','世界著名建筑','建成于1889年','法国工业革命的象征','埃菲尔铁塔,法国,建筑','城市建筑','#0000FF'),(27,'金字塔','埃及','https://example.com/world3.jpg','埃及古代法老的陵墓','世界文化遗产','始建于公元前2600年','古埃及文明的象征','金字塔,埃及,历史','历史建筑','#FFFF00'),(28,'悉尼歌剧院','澳大利亚','https://example.com/world4.jpg','澳大利亚悉尼的标志性建筑','世界文化遗产','建成于1973年','现代建筑的代表','悉尼歌剧院,澳大利亚,建筑','现代建筑','#00FF00'),(29,'自由女神像','美国','https://example.com/world5.jpg','美国纽约的标志性建筑','世界文化遗产','建成于1886年','自由和民主的象征','自由女神像,美国,建筑','城市建筑','#00FFFF'),(30,'泰姬陵','印度','https://example.com/world6.jpg','印度阿格拉的标志性建筑','世界文化遗产','建成于1653年','爱情的象征','泰姬陵,印度,建筑','历史建筑','#FF00FF'),(31,'大本钟','英国','https://example.com/world7.jpg','英国伦敦的标志性建筑','世界著名建筑','建成于1859年','英国议会制度的象征','大本钟,英国,建筑','城市建筑','#FFA500'),(32,'东京塔','日本','https://example.com/world8.jpg','日本东京的标志性建筑','世界著名建筑','建成于1958年','日本战后复兴的象征','东京塔,日本,建筑','城市建筑','#800080'),(33,'圣索菲亚大教堂','土耳其','https://example.com/world9.jpg','土耳其伊斯坦布尔的标志性建筑','世界文化遗产','建成于537年','拜占庭建筑的代表','圣索菲亚大教堂,土耳其,建筑','历史建筑','#008000'),(34,'罗马斗兽场','意大利','https://example.com/world10.jpg','意大利罗马的标志性建筑','世界文化遗产','建成于80年','古罗马文明的象征','罗马斗兽场,意大利,历史','历史建筑','#800000'),(35,'长城','中国','https://picsum.photos/seed/wc1/800/600','世界上最长的古代防御工程，蜿蜒于崇山峻岭之间。','全长超2万公里，跨越多个省份，气势磅礴。','始建于春秋战国，秦始皇连接各段，明代大规模修筑。','中华民族坚韧不拔精神的象征，世界文化遗产。','世界遗产,古代建筑,奇迹,历史','建筑','#8B4513'),(36,'故宫','中国','https://picsum.photos/seed/wc2/800/600','明清两代皇家宫殿，世界最大古代宫殿建筑群。','红墙黄瓦，中轴对称，9999间半房屋。','始建于明永乐年间，历24位皇帝。','中国古代宫廷建筑巅峰，中华文明瑰宝。','世界遗产,宫殿,博物馆,历史','建筑','#B22222'),(37,'兵马俑','中国','https://picsum.photos/seed/wc3/800/600','秦始皇陵陪葬坑，世界第八大奇迹。','数千陶俑陶马，千人千面，栩栩如生。','建于公元前246年，1974年被发现。','秦代军事与雕塑艺术巅峰，中华文明象征。','世界遗产,考古,雕塑,历史','文物','#A0522D'),(38,'布达拉宫','中国','https://picsum.photos/seed/wc4/800/600','世界屋脊上的明珠，藏式建筑巅峰之作。','依山而建，红白相间，气势恢宏。','始建于7世纪，17世纪重建。','藏传佛教圣地，藏族文化象征。','世界遗产,宫殿,宗教,藏文化','建筑','#DC143C'),(39,'西湖','中国','https://picsum.photos/seed/wc5/800/600','中国十大风景名胜之一，人间天堂。','三面云山一面城，四季景色各异。','自古文人墨客吟咏之地，白居易、苏轼治理。','中国山水园林文化典范，世界文化景观遗产。','世界遗产,自然景观,湖泊,文化','自然景观','#2E8B57'),(40,'埃菲尔铁塔','法国','https://picsum.photos/seed/wc6/800/600','巴黎地标，世界最著名铁塔。','高324米，镂空钢结构，夜景璀璨。','1889年为世博会而建，居斯塔夫·埃菲尔设计。','法国工业革命象征，浪漫巴黎的代名词。','地标,建筑,铁塔,浪漫','建筑','#8B8378'),(41,'卢浮宫','法国','https://picsum.photos/seed/wc7/800/600','世界最大艺术博物馆之一，艺术殿堂。','玻璃金字塔入口，藏品超38万件。','始建于12世纪，原为皇宫，1793年改为博物馆。','人类艺术瑰宝汇聚地，蒙娜丽莎的微笑。','博物馆,艺术,宫殿,历史','建筑','#DAA520'),(42,'凡尔赛宫','法国','https://picsum.photos/seed/wc8/800/600','法国皇家宫殿，欧洲宫廷典范。','镜厅、花园、喷泉，奢华极致。','建于17世纪，路易十四时期。','法国绝对君主制象征，巴洛克艺术代表。','世界遗产,宫殿,花园,历史','建筑','#FFD700'),(43,'自由女神像','美国','https://picsum.photos/seed/wc9/800/600','纽约港标志，自由与民主象征。','高93米，铜制雕像，手持火炬。','1886年法国赠予美国，庆祝独立百年。','美国精神象征，移民希望的灯塔。','世界遗产,地标,雕像,自由','建筑','#2F4F4F'),(44,'大峡谷','美国','https://picsum.photos/seed/wc10/800/600','世界七大自然奇观之一，地质奇观。','长446公里，深1600米，科罗拉多河切割。','形成于600万年前，印第安人世代居住。','美国自然遗产象征，地球地质史书。','自然景观,峡谷,地质,国家公园','自然景观','#CD853F'),(45,'金门大桥','美国','https://picsum.photos/seed/wc11/800/600','旧金山地标，世界最著名悬索桥之一。','全长2737米，红色桥身，雾中若隐若现。','1937年建成，被誉为工程奇迹。','旧金山象征，美国工程实力代表。','地标,桥梁,建筑,工程','建筑','#B22222'),(46,'大本钟','英国','https://picsum.photos/seed/wc12/800/600','伦敦地标，英国议会大厦钟楼。','钟声悠扬，哥特式建筑，高96米。','1859年建成，二战期间屹立不倒。','英国民主与时间象征，伦敦声音。','地标,建筑,钟楼,历史','建筑','#8B7500'),(47,'白金汉宫','英国','https://picsum.photos/seed/wc13/800/600','英国王室官邸，皇家象征。','卫兵换岗仪式，皇家花园，宫殿700余间。','1703年始建，1837年成为王室官邸。','英国君主制象征，皇家文化代表。','宫殿,王室,历史,建筑','建筑','#DAA520'),(48,'巨石阵','英国','https://picsum.photos/seed/wc14/800/600','史前巨石建筑，世界未解之谜。','巨大石块排列成圆，重达25吨。','建于公元前3000-2000年，用途至今成谜。','史前人类智慧象征，世界文化遗产。','世界遗产,史前,神秘,考古','文物','#696969'),(49,'罗马斗兽场','意大利','https://picsum.photos/seed/wc15/800/600','古罗马圆形竞技场，帝国象征。','可容纳5万观众，椭圆形结构。','建于公元72-80年，用于角斗表演。','古罗马文明象征，世界文化遗产。','世界遗产,古罗马,竞技场,历史','建筑','#A0522